import { describe, expect, it, vi } from "vitest";
import { AbstractAgent } from "@ag-ui/client";
import { DeliveryAdapter } from "./delivery-adapter.js";
class TestAgent extends AbstractAgent {
    run(_input) {
        throw new Error("unused");
    }
    async runAgent(_parameters, _subscriber) {
        return { result: undefined, newMessages: [] };
    }
    clone() {
        const c = new TestAgent({ agentId: this.agentId });
        c.threadId = this.threadId;
        c.messages = structuredClone(this.messages);
        return c;
    }
}
function prepared(deliveryId) {
    return {
        protocol: "channel_delivery_v1",
        deliveryId,
        deliveryExpiresAt: "2099-07-29T17:00:00.000Z",
        channelId: "channel_1",
        channelName: "support",
        canonicalThreadId: "thread_shared",
        appUserId: "slack:T1:U1",
        adapter: "slack",
        turn: {
            eventId: `evt_${deliveryId}`,
            receivedAt: "2026-07-29T17:00:00.000Z",
            input: {
                kind: "text",
                text: "hi",
                messageRef: { id: "pref_v1_message_concurrency_123" },
                operation: {
                    kind: "created",
                    logicalMessageId: "pid_v1_abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQ",
                    revisionId: "pid_v1_ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopq",
                    mentioned: false,
                },
            },
            actor: { externalUserId: "U1", kind: "human" },
        },
    };
}
describe("DeliveryAdapter concurrent same-thread runs", () => {
    it("allows two concurrent getOrCreate calls for the same canonical thread", async () => {
        let release1;
        const gate1 = new Promise((r) => {
            release1 = r;
        });
        let loadCalls = 0;
        const gated = new DeliveryAdapter({
            channelName: "support",
            transport: {},
            runCanonical: async () => ({ iterations: 0, interrupted: false }),
            loadHistory: async () => {
                loadCalls++;
                if (loadCalls === 1)
                    await gate1;
                return [];
            },
        });
        const session = {};
        const d1 = {
            ...prepared("dlv_1"),
            turn: {
                ...prepared("dlv_1").turn,
                input: { kind: "welcome" },
            },
        };
        const d2 = {
            ...prepared("dlv_2"),
            turn: {
                ...prepared("dlv_2").turn,
                input: { kind: "welcome" },
            },
        };
        const makeAgent = (id) => {
            const a = new TestAgent({ agentId: "t" });
            a.threadId = id;
            return a;
        };
        const p1 = gated.conversationStore.getOrCreate(d1.canonicalThreadId, { claimedDelivery: session, delivery: d1 }, makeAgent);
        const p2 = gated.conversationStore.getOrCreate(d2.canonicalThreadId, { claimedDelivery: session, delivery: d2 }, makeAgent);
        // Both must be in flight — the second must not be rejected for overlapping.
        await vi.waitFor(() => expect(loadCalls).toBeGreaterThanOrEqual(1));
        release1();
        const [s1, s2] = await Promise.all([p1, p2]);
        expect(s1.agent).not.toBe(s2.agent);
        s1.release?.();
        s2.release?.();
    });
});
